#include <vector>
#include <string>

class Solution {
public:
    std::vector<bool> canMakePalindromeQueries(int n, std::vector<std::vector<int>>& edges, std::string s, std::vector<std::vector<int>>& queries) {
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        std::vector<int> parent(n, 0), depth(n, 0), mask(n, 0);
        std::vector<bool> visited(n, false);
        visited[0] = true;
        mask[0] = 1 << (s[0] - 'a');
        std::vector<int> q = {0};
        int head = 0;
        while (head < (int)q.size()) {
            int u = q[head++];
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    mask[v] = mask[u] ^ (1 << (s[v] - 'a'));
                    q.push_back(v);
                }
            }
        }
        auto getLca = [&](int u, int v) {
            while (depth[u] > depth[v]) u = parent[u];
            while (depth[v] > depth[u]) v = parent[v];
            while (u != v) {
                u = parent[u];
                v = parent[v];
            }
            return u;
        };
        std::vector<bool> ans;
        for (const auto& qry : queries) {
            int u = qry[0], v = qry[1];
            int lca = getLca(u, v);
            int path_mask = mask[u] ^ mask[v] ^ (1 << (s[lca] - 'a'));
            ans.push_back((path_mask & (path_mask - 1)) == 0);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public boolean[] canMakePalindromeQueries(int n, int[][] edges, String s, int[][] queries) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        int[] parent = new int[n];
        int[] depth = new int[n];
        int[] mask = new int[n];
        boolean[] visited = new boolean[n];
        visited[0] = true;
        mask[0] = 1 << (s.charAt(0) - 'a');
        Queue<Integer> q = new LinkedList<>();
        q.offer(0);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    mask[v] = mask[u] ^ (1 << (s.charAt(v) - 'a'));
                    q.offer(v);
                }
            }
        }
        boolean[] ans = new boolean[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int u = queries[i][0], v = queries[i][1];
            int a = u, b = v;
            while (depth[a] > depth[b]) a = parent[a];
            while (depth[b] > depth[a]) b = parent[b];
            while (a != b) { a = parent[a]; b = parent[b]; }
            int lca = a;
            int pathMask = mask[u] ^ mask[v] ^ (1 << (s.charAt(lca) - 'a'));
            ans[i] = (pathMask & (pathMask - 1)) == 0;
        }
        return ans;
    }
}

